package variables;

public class Task13 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		double salary = 25000;
        double increment = salary * 0.10;
        double newSalary = salary + increment;
        System.out.println("Original Salary: " + salary);
        System.out.println("Increment (10%): " + increment);
        System.out.println("Salary After Increment: " + newSalary);
	}

}
